<script setup lang="ts">import{ref}from'vue';import DefaultLayout from'@/layouts/DefaultLayout.vue';import BaseInput from'@/components/ui/BaseInput.vue';import BaseButton from'@/components/ui/BaseButton.vue';import{useApi}from'@/composables/useApi';const api=useApi(),currentPassword=ref(''),newPassword=ref(''),confirmNewPassword=ref(''),message=ref(''),error=ref('');async function save(){error.value='';if(newPassword.value===currentPassword.value){error.value='Mật khẩu mới không được giống mật khẩu hiện tại';return}if(newPassword.value!==confirmNewPassword.value){error.value='Mật khẩu xác nhận không khớp';return}try{await api.patch('/users/me/password',{currentPassword:currentPassword.value,newPassword:newPassword.value,confirmNewPassword:confirmNewPassword.value});message.value='Đổi mật khẩu thành công';currentPassword.value=newPassword.value=confirmNewPassword.value=''}catch(e){error.value=e instanceof Error?e.message:'Không thể đổi mật khẩu'}}</script>
<template><DefaultLayout><main class="mx-auto max-w-2xl px-4 py-12"><h1 class="text-3xl font-black">Đổi mật khẩu</h1><form class="mt-7 space-y-5 rounded-2xl border bg-white p-6 dark:border-slate-800 dark:bg-slate-900" @submit.prevent="save"><BaseInput id="current-password" v-model="currentPassword" type="password" label="Mật khẩu hiện tại" required/><BaseInput id="new-password" v-model="newPassword" type="password" label="Mật khẩu mới" required/><BaseInput id="confirm-new-password" v-model="confirmNewPassword" type="password" label="Xác nhận mật khẩu mới" required/><p v-if="message" class="text-emerald-600">{{message}}</p><p v-if="error" class="text-red-600">{{error}}</p><BaseButton type="submit" :loading="api.loading.value">Đổi mật khẩu</BaseButton></form></main></DefaultLayout></template>
